import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    # Create a low-mass, stable chassis
    chassis = sandbox.add_beam(x=10.0, y=2.0, width=0.5, height=0.5, density=1.0)
    sandbox.set_material_properties(chassis, restitution=0.1, friction=0.8)

    # Add two wheels with optimal ground contact
    wheel_radius = 0.25
    wheel_y = 1.0 + wheel_radius  # Ensure wheels are on ground (y=1.0)
    wheel1 = sandbox.add_wheel(x=10.0 - 1.0, y=wheel_y, radius=wheel_radius, density=1.0)
    wheel2 = sandbox.add_wheel(x=10.0 + 1.0, y=wheel_y, radius=wheel_radius, density=1.0)

    # Connect wheels to chassis with pivot joints
    joint1 = sandbox.add_joint(chassis, wheel1, (10.0 - 1.0, wheel_y), type='pivot')
    joint2 = sandbox.add_joint(chassis, wheel2, (10.0 + 1.0, wheel_y), type='pivot')

    return {"body": chassis, "joints": [joint1, joint2]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    # Adjust motor speed dynamically to maintain forward motion
    if step_count > 50000:
        motor_speed = -5.0  # Sustain forward motion without excessive spinning
    else:
        motor_speed = -10.0  # Initial high speed to overcome static friction
    for joint in joints:
        sandbox.set_motor(joint, motor_speed, max_torque=100.0)
